using FlowPilot.Application.ExternalIntegrations.Jitsi;
using FlowPilot.Application.Nexus.Identity.Users.Models.Response;
using JWT.Algorithms;
using JWT.Builder;
using Microsoft.Extensions.Options;

namespace FlowPilot.Infrastructure.ExternalIntegrations.Jitsi;
public class JitsiService : IJitsiService
{
    private readonly JitsiSettings _jitsiSettings;
    public JitsiService(IOptions<JitsiSettings> jitsiSettings)
    {
        _jitsiSettings = jitsiSettings.Value;
    }

    public string GenerateToken(string roomName, bool isModerator, ViewUserDetailsResponse viewUserDetailsResponse)
    {

        string token = JwtBuilder.Create()
                              .WithAlgorithm(new HMACSHA256Algorithm()) // symmetric
                              .WithSecret(_jitsiSettings.Key)
                              .AddClaim("exp", DateTimeOffset.Now.AddMinutes(30).ToUnixTimeSeconds())
                              .AddClaim("room", _jitsiSettings)
                              .AddClaim("sub", _jitsiSettings.Sub)
                              .AddClaim("moderator", isModerator)
                              .AddClaim("context", new
                              {
                                  user = new
                                  {
                                      name = viewUserDetailsResponse.FirstName + " " + viewUserDetailsResponse.LastName,
                                      id = viewUserDetailsResponse.Id,
                                      //avatar = "data:image/jpeg;base64,"
                                  }
                              })
                              .AddClaim("aud", _jitsiSettings.Issuer)
                              .AddClaim("iss", _jitsiSettings.Issuer)
                              .Encode();

        return token;
    }


}
